package com.bank.growth;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.logging.Logger;

// Projects fixed-deposit growth for National Bank of India using powers.
public class GrowthProjector {
    private static final Logger log = Logger.getLogger(GrowthProjector.class.getName());

    // Naive recursion: power(x,n) = x * power(x,n-1), base power(x,0)=1. O(n).
    public BigDecimal powerNaive(BigDecimal x, int n) {
        if (n == 0) return BigDecimal.ONE;          // base case
        return x.multiply(powerNaive(x, n - 1));    // recursive case
    }

    // Fast recursion by squaring: O(log n), safe for large exponents.
    public BigDecimal powerFast(BigDecimal x, int n) {
        if (n == 0) return BigDecimal.ONE;
        BigDecimal half = powerFast(x, n / 2);      // compute half power once
        BigDecimal squared = half.multiply(half);   // square it
        return (n % 2 == 0) ? squared : squared.multiply(x);
    }

    // Projects principal * factor^years, scaled to paise with rounding.
    public BigDecimal project(BigDecimal principal, BigDecimal factor, int years) {
        BigDecimal grown = powerFast(factor, years);
        BigDecimal value = principal.multiply(grown).setScale(2, RoundingMode.HALF_UP);
        log.info(() -> "Projected value after " + years + " years = Rs." + value);
        return value;
    }
}
