package com.bank.growth;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: project Rajesh's fixed deposit over short and long horizons.
public class GrowthDemo {
    private static final Logger log = Logger.getLogger(GrowthDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        GrowthProjector projector = new GrowthProjector();

        BigDecimal principal = new BigDecimal("1000000");   // Rajesh SAV2001 FD
        BigDecimal factor    = new BigDecimal("1.07");       // 7% annual growth

        BigDecimal shortTerm = projector.project(principal, factor, 5);
        log.info(() -> "Rajesh 5-year projection: Rs." + shortTerm);

        BigDecimal longTerm = projector.project(principal, factor, 30);
        log.info(() -> "Rajesh 30-year retirement projection: Rs." + longTerm);
    }
}
